import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"益","description":"周易正义 - 益","frontmatter":{"title":"益","description":"周易正义 - 益"},"headers":[],"relativePath":"zh/classics/zhengyi/042.md","filePath":"zh/classics/zhengyi/042.md"}'),l={name:"zh/classics/zhengyi/042.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>风雷益</p></blockquote><blockquote><p>卦辞：利有攸往，利涉大川。</p></blockquote><blockquote><p>彖曰：益，损上益下，民说无疆。自上下下，其道大光。利有攸往，中正有庆。利涉大川，木道乃行。益动而巽，日进无疆。天施地生，其益无方。凡益之道，与时偕行。</p></blockquote><h1 id="益" tabindex="-1">益 <a class="header-anchor" href="#益" aria-label="Permalink to “益”">​</a></h1><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“益”者，增足之名，损上益下，故谓之益。下巳有矣，而上更益之，明圣人利物之无巳也。损卦则损下益上，益卦则损上益下，得名皆就下而不据上者，向秀云：“明王之道，志在惠下，故取下谓之损，与下谓之益。”既上行惠下之道，利益万物，动而无违，何往不利，故曰“利有攸往”。以益涉难，理绝险阻，故曰“利涉大川”。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="益-损上益下-民说无疆。-​" tabindex="-1">益，损上益下，民说无疆。 ​ <a class="header-anchor" href="#益-损上益下-民说无疆。-​" aria-label="Permalink to “益，损上益下，民说无疆。 ​”">​</a></h3><p>王弼：震，阳也。巽，阴也。巽非违震者也。处上而巽，不违於下，“损上益下”之谓也。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：此就二体释卦名之义。柔损在上，刚动在下，上巽不违於下，“损上益下”之义也。既居上者能自损以益下，则下民欢说，无复疆限。益卦所以名益者，正以“损上益下，民说无疆”者也。</p><h3 id="自上下下-其道大光。-利有攸往-中正有庆。-​" tabindex="-1">自上下下，其道大光。“利有攸往”，中正有庆。 ​ <a class="header-anchor" href="#自上下下-其道大光。-利有攸往-中正有庆。-​" aria-label="Permalink to “自上下下，其道大光。“利有攸往”，中正有庆。 ​”">​</a></h3><p>王弼：五处中正，“自上下下”，故“有庆”也。以中正有庆之德，有攸往也，何適而不利哉！</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：此就九五之爻，释“利有攸往，中正有庆”也。五处中正，能“自上下下”，则其道光大，为天下之所庆顺也。“以中正有庆之德”，故所往无不利焉。益之所以“利有攸往”者，正谓中正有庆故也。</p><h3 id="利涉大川-木道乃行。-​" tabindex="-1">利涉大川，木道乃行。 ​ <a class="header-anchor" href="#利涉大川-木道乃行。-​" aria-label="Permalink to “利涉大川，木道乃行。 ​”">​</a></h3><p>王弼：木者，以涉大川为常而不溺者也。以益涉难，同乎“木”也。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：此取譬以释“利涉大川”也。木体轻浮，以涉大川为常而不溺也。以益涉难，如木道之涉川。涉川无害，方见益之为利，故云“利涉大川，木道乃行”也。</p><h3 id="益动而巽-日进无疆。天施地生-其益无方。-​" tabindex="-1">益动而巽，日进无疆。天施地生，其益无方。 ​ <a class="header-anchor" href="#益动而巽-日进无疆。天施地生-其益无方。-​" aria-label="Permalink to “益动而巽，日进无疆。天施地生，其益无方。 ​”">​</a></h3><p>王弼：损下益下。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“益动而巽，日进无疆”者，自此已下，广明益义。前则就二体明损上益下以释卦名，以下有动求，上能巽接，是“损上益下”之义。今执二体更明得益之方也。若动而骄盈，则彼损无已。若动而卑巽，则进益无疆，故曰“益动而巽，日进无疆”。“天施地生，其益无方”者，此就天地广明益之大义也。天施气於地，地受气而化生，亦是“损上益下”义也。其施化之益，无有方所，故曰“天施地生，其益无方”。</p><h3 id="凡益之道-与时偕行。-​" tabindex="-1">凡益之道，与时偕行。 ​ <a class="header-anchor" href="#凡益之道-与时偕行。-​" aria-label="Permalink to “凡益之道，与时偕行。 ​”">​</a></h3><p>王弼：益之为用，施未足也。满而益之，害之道也。故“凡益之道，与时偕行”也。</p><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：虽施益无方，不可恒用，当应时行之，故举“凡益”总结之，故曰“凡益之道，与时偕行也”。</p><h3 id="《象》曰-风雷-益。君子以见善则迁-有过则改。-​" tabindex="-1">《象》曰：风雷，益。君子以见善则迁，有过则改。 ​ <a class="header-anchor" href="#《象》曰-风雷-益。君子以见善则迁-有过则改。-​" aria-label="Permalink to “《象》曰：风雷，益。君子以见善则迁，有过则改。 ​”">​</a></h3><p>王弼：迁善改过，益莫大焉。</p><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：《子夏传》云：“雷以动之，风以散之，万物皆盈。”孟僖亦与此同其意。言必须雷动於前，风散於后，然后万物皆益。如二月启蛰之后，风以长物八月收声之后，风以残物。风之为益，其在雷后，故曰“风雷，益”也。迁谓迁徙慕尚，改谓改更惩止，迁善改过，益莫大焉，故君子求益，以“见善则迁，有过则改”也。六子之中，并有益物，犹取雷风者，何晏云：“取其最长可久之义也。”</p><h2 id="初九-利用为大作-元吉-无咎。-​" tabindex="-1">初九：利用为大作，元吉，无咎。 ​ <a class="header-anchor" href="#初九-利用为大作-元吉-无咎。-​" aria-label="Permalink to “初九：利用为大作，元吉，无咎。 ​”">​</a></h2><p>王弼：处益之初，居动之始。体夫刚德，以莅其事而之乎巽，以斯大作，必获大功。夫居下非“厚事”之地，在卑非任重之处，大作非小功所济，故“元吉”，乃得“无咎”也。</p><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“大作”谓兴作大事也。初九处益之初，居动之始，有兴作大事之端，又体刚能幹，应巽不违，有堪建大功之德，故曰“利用为大作”也。然有其才而无其位，得其时而无其处，虽有殊功，人不与也。时人不与，则咎过生焉。故必“元吉”，乃得“无咎”，故曰“元吉，无咎”。</p><h3 id="《象》曰-元吉-无咎-下不厚事也。-​" tabindex="-1">《象》曰：“元吉，无咎”，下不厚事也。 ​ <a class="header-anchor" href="#《象》曰-元吉-无咎-下不厚事也。-​" aria-label="Permalink to “《象》曰：“元吉，无咎”，下不厚事也。 ​”">​</a></h3><p>王弼：时可以大作，而下不可以厚事，得其时而无其处，故“元吉”，乃得“无咎”也。</p><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“下不厚事”者，厚事犹大事也。</p><h2 id="六二-或益之十朋之龟-弗克违-永贞吉。王用享于帝-吉。-​" tabindex="-1">六二：或益之十朋之龟，弗克违，永贞吉。王用享于帝，吉。 ​ <a class="header-anchor" href="#六二-或益之十朋之龟-弗克违-永贞吉。王用享于帝-吉。-​" aria-label="Permalink to “六二：或益之十朋之龟，弗克违，永贞吉。王用享于帝，吉。 ​”">​</a></h2><p>王弼：以柔居中，而得其位。处内履中，居益以冲。益自外来，不召自至，不先不违，则朋龟献策，同於损卦六五之位，位不当尊故吉在“永贞”也。帝者，生物之主，兴益之宗，出震而齐巽者也。六二居益之中，体柔当位，而应於巽，享帝之美，在此时也。</p><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>“六二”至“王用享于帝吉”。○正义曰：六二体柔居中，当位应巽，是居益而能用谦冲者也。居益用谦，则物“自外来”，朋龟献策，弗能违也。同於损卦六五之位，故曰“或益之十朋之龟，弗克违”也。然位不当尊，故永贞乃吉，故曰“永贞吉”。帝，天也。王用此时，以享祭於帝，明灵降福，故曰“王用享於帝吉”也。</p><h3 id="《象》曰-或益之-自外来也。-​" tabindex="-1">《象》曰：“或益之”，自外来也。 ​ <a class="header-anchor" href="#《象》曰-或益之-自外来也。-​" aria-label="Permalink to “《象》曰：“或益之”，自外来也。 ​”">​</a></h3><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“自外来”者，明益之者从外自来，不召而至也。</p><h2 id="六三-益之-用凶事-无咎。有孚中行-告公用圭。-​" tabindex="-1">六三：益之，用凶事，无咎。有孚中行，告公用圭。 ​ <a class="header-anchor" href="#六三-益之-用凶事-无咎。有孚中行-告公用圭。-​" aria-label="Permalink to “六三：益之，用凶事，无咎。有孚中行，告公用圭。 ​”">​</a></h2><p>王弼：以阴居阳，求益者也。故曰“益之”。益不外来，己自为之，物所不与，故在谦则戮，救凶则免。以阴居阳，处下卦之上，壮之甚也。用救衰危，物所恃也，故“用凶事”，乃得“无咎”也。若能益不为私，志在救难，壮不至亢，不失中行，以此告公，国主所任也；用圭之礼，备此道矣，故曰“有孚，中行，告公用圭”也。公者，臣之极也。凡事足以施天下，则称王，次天下之大者，则称公。六三之才，不足以告王，足以告公，而得用圭也。故曰“中行告公用圭”也。</p><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>“六三”至“告公用圭”。○正义曰：六三以阴居阳，不能谦退，是求益者也，故曰“益之”。“益不外来，已自为之，物所不与”。若以谦道责之，则理合诛戮。若以救凶原之，则情在可恕。然此六三，“以阴居阳，处下卦之上，壮之甚也”。用此以救衰危，则物之所恃，所以“用凶事”而得免咎，故曰“益之，用凶事，无咎”。若能求益不为私己，志在救难，为壮不至亢极，能適於时，是有信实而得中行，故曰“有孚中行”也。用此“有孚中行”之德，执圭以告於公，公必任之以救衰危之事，故曰“告公用圭”。○注“以阴居阳”至“告公用圭也”。○正义曰：告王者宜以文德燮理，使天下人宁，不当恒以救凶，用志褊狭也。</p><h3 id="《象》曰-益-用凶事-固有之也。-​" tabindex="-1">《象》曰：益“用凶事”，固有之也。 ​ <a class="header-anchor" href="#《象》曰-益-用凶事-固有之也。-​" aria-label="Permalink to “《象》曰：益“用凶事”，固有之也。 ​”">​</a></h3><p>王弼：用施凶事，乃得固有之也。</p><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“固有之”者，明其为救凶，则不可求益；施之凶事，乃得固有其功也。</p><h2 id="六四-中行-告公从-利用为依迁国。-​" tabindex="-1">六四：中行，告公从，利用为依迁国。 ​ <a class="header-anchor" href="#六四-中行-告公从-利用为依迁国。-​" aria-label="Permalink to “六四：中行，告公从，利用为依迁国。 ​”">​</a></h2><p>王弼：居益之时，处巽之始，体柔当位，在上应下。卑不穷下，高不处亢，位虽不中，用“中行”者也。以斯告公，何有不从？以斯“依迁”，谁有不纳也？</p><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：六四：居益之时，处巽之始，体柔当位，在上应下，卑不穷下，高不处亢，位虽不中，用中行者也”，故曰“中行”也。以此中行之德，有事以告於公，公必从之，故曰“告公从”也。用此道以依人而迁国者，人无不纳，故曰“利用为依迁国”也。迁国，国之大事，明以中行，虽有大事，而无不利，如“周之东迁晋郑焉依”之义也。</p><h3 id="《象》曰-告公从-以益志也。志得益也。-​" tabindex="-1">《象》曰：“告公从”，以益志也。志得益也。 ​ <a class="header-anchor" href="#《象》曰-告公从-以益志也。志得益也。-​" aria-label="Permalink to “《象》曰：“告公从”，以益志也。志得益也。 ​”">​</a></h3><h3 id="疏-14" tabindex="-1">疏 <a class="header-anchor" href="#疏-14" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“以益志”者，既为公所从，其志得益也。</p><h2 id="九五-有孚惠心-勿问元吉。有孚-惠我德。-​" tabindex="-1">九五：有孚惠心，勿问元吉。有孚，惠我德。 ​ <a class="header-anchor" href="#九五-有孚惠心-勿问元吉。有孚-惠我德。-​" aria-label="Permalink to “九五：有孚惠心，勿问元吉。有孚，惠我德。 ​”">​</a></h2><p>王弼：得位履尊，为益之主者也。为益之大，莫大於信。为惠之大，莫大於心。因民所利而利之焉，惠而不费，惠心者也。信以惠心，尽物之愿，固不待问而“元吉有孚惠我德”也。以诚惠物，物亦应之，故曰“有孚惠我德”也。</p><h3 id="疏-15" tabindex="-1">疏 <a class="header-anchor" href="#疏-15" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：九五得位处尊，为益之主，兼张德义，以益物者也。“为益之大，莫大於信，为惠之大，莫大於心。因民所利而利之焉，惠而不费，惠心者也”。有惠有信，尽物之愿，必获元吉，不待疑问，故曰“有孚惠心，勿问元吉”。我既以信，惠被於物，物亦以信，惠归於我，故曰“有孚，惠我德”也。</p><h3 id="《象》曰-有孚惠心-勿问之矣。-惠我德-大得志也。-​" tabindex="-1">《象》曰：“有孚惠心”，勿问之矣。“惠我德”，大得志也。 ​ <a class="header-anchor" href="#《象》曰-有孚惠心-勿问之矣。-惠我德-大得志也。-​" aria-label="Permalink to “《象》曰：“有孚惠心”，勿问之矣。“惠我德”，大得志也。 ​”">​</a></h3><h3 id="疏-16" tabindex="-1">疏 <a class="header-anchor" href="#疏-16" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“大得志”者，天下皆以信惠归我，则可以得志於天下，故曰“大得志”也。</p><h2 id="上九-莫益之-或击之-立心勿恒-凶。-​" tabindex="-1">上九：莫益之，或击之，立心勿恒，凶。 ​ <a class="header-anchor" href="#上九-莫益之-或击之-立心勿恒-凶。-​" aria-label="Permalink to “上九：莫益之，或击之，立心勿恒，凶。 ​”">​</a></h2><p>王弼：处益之极，过盈者也。求益无巳，心无恒者也。无厌之求，人弗与也。独唱莫和，是“偏辞也”。人道恶盈，怨者非一，故曰“或击之”也。</p><h3 id="疏-17" tabindex="-1">疏 <a class="header-anchor" href="#疏-17" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：上九处益之极，益之过甚者也。求益无厌，怨者非一，故曰“莫益之，或击之”也。勿犹无也，求益无己，是“立心无恒”者也。无恒之人，必凶咎之所集，故曰“立心勿恒，凶”。</p><h3 id="《象》曰-莫益之-偏辞也。-或击之-自外来也。-​" tabindex="-1">《象》曰：“莫益之”，偏辞也。“或击之”，自外来也。 ​ <a class="header-anchor" href="#《象》曰-莫益之-偏辞也。-或击之-自外来也。-​" aria-label="Permalink to “《象》曰：“莫益之”，偏辞也。“或击之”，自外来也。 ​”">​</a></h3><h3 id="疏-18" tabindex="-1">疏 <a class="header-anchor" href="#疏-18" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“偏辞”者，此有求而彼不应，是“偏辞也”。“自外来”者，怨者非一，不待召也，故曰“自外来也”。</p>',75)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
